// ==== 17-auth.js ====
// ---------- Accounts (Supabase Auth) ----------
// Shared across every page that includes this script (index.html, account.html). Handles
// sign up / log in / log out and keeps the header's auth chip in sync. Other scripts (like
// 14-alchemypay.js and account.html's own page script) listen for the 'cw:auth' event on
// `document` rather than reaching into this module directly, so load order doesn't matter:
//   document.addEventListener('cw:auth', (e) => { const user = e.detail.user; ... });
// `window.cwAuth.getUser()` is also available for a one-off synchronous-ish read (returns
// whatever the last known session was; null until the initial session check resolves).

(function () {
    let supabaseClient = null;
    let currentUser = null;
    let configured = false;
    let resolved = false; // true once the initial getSession() check has completed at least once
    const changeListeners = [];

    if (typeof CW_CONFIG !== 'undefined' && CW_CONFIG.supabaseUrl && CW_CONFIG.supabaseAnonKey && typeof supabase !== 'undefined') {
        try {
            supabaseClient = supabase.createClient(CW_CONFIG.supabaseUrl, CW_CONFIG.supabaseAnonKey);
            configured = true;
        } catch (err) {
            console.error('[CryptoBolt] Failed to initialize Supabase client:', err.message);
        }
    } else {
        console.info('[CryptoBolt] Supabase not configured — accounts are disabled until supabaseUrl/supabaseAnonKey are set in js/00-config.js.');
    }

    function broadcastAuth() {
        resolved = true;
        document.dispatchEvent(new CustomEvent('cw:auth', { detail: { user: currentUser, configured } }));
        changeListeners.forEach(cb => cb(currentUser, configured));
    }

    window.cwAuth = {
        getUser: () => currentUser,
        isConfigured: () => configured,
        getClient: () => supabaseClient,
        // Registers a callback for auth state changes. If the initial session check has already
        // resolved by the time this is called (a real possibility — supabase-js can resolve
        // getSession() from a cached local session before the next <script> tag even runs), the
        // callback fires immediately with the current state instead of only on the NEXT change.
        // This is the safe way for another page script to learn the current user; listening for
        // the 'cw:auth' document event alone can race and miss the first broadcast.
        onChange: (callback) => {
            changeListeners.push(callback);
            if (resolved) callback(currentUser, configured);
        },
    };

    // ---------- Header chip (present on any page that includes this markup) ----------
    const openBtn = document.getElementById('auth-open-btn');
    const userChip = document.getElementById('auth-user-chip');
    const userEmailEl = document.getElementById('auth-user-email');
    const signOutBtn = document.getElementById('auth-signout-btn');

    function renderHeader() {
        if (!openBtn || !userChip) return;
        if (currentUser) {
            openBtn.classList.add('hidden');
            userChip.classList.remove('hidden');
            userChip.classList.add('flex');
            if (userEmailEl) userEmailEl.title = currentUser.email || '';
        } else {
            openBtn.classList.remove('hidden');
            userChip.classList.add('hidden');
            userChip.classList.remove('flex');
        }
    }

    if (signOutBtn) {
        signOutBtn.addEventListener('click', async () => {
            if (!supabaseClient) return;
            await supabaseClient.auth.signOut();
        });
    }

    // ---------- Auth modal (sign up / log in / forgot password) ----------
    const modal = document.getElementById('auth-modal');
    if (modal) {
        const tabSignIn = document.getElementById('auth-tab-signin');
        const tabSignUp = document.getElementById('auth-tab-signup');
        const emailInput = document.getElementById('auth-email-input');
        const passwordInput = document.getElementById('auth-password-input');
        const submitBtn = document.getElementById('auth-submit-btn');
        const errorEl = document.getElementById('auth-error');
        const infoEl = document.getElementById('auth-info');
        const forgotLink = document.getElementById('auth-forgot-link');
        const configWarning = document.getElementById('auth-config-warning');
        let mode = 'signin'; // 'signin' | 'signup'

        function setMode(next) {
            mode = next;
            tabSignIn.classList.toggle('auth-tab-active', mode === 'signin');
            tabSignUp.classList.toggle('auth-tab-active', mode === 'signup');
            submitBtn.innerText = mode === 'signin' ? 'Sign In' : 'Create Account';
            forgotLink.classList.toggle('hidden', mode !== 'signin');
            errorEl.classList.add('hidden');
            infoEl.classList.add('hidden');
        }
        tabSignIn?.addEventListener('click', () => setMode('signin'));
        tabSignUp?.addEventListener('click', () => setMode('signup'));

        function openModal() {
            if (!configured) {
                configWarning?.classList.remove('hidden');
            } else {
                configWarning?.classList.add('hidden');
            }
            errorEl.classList.add('hidden');
            infoEl.classList.add('hidden');
            emailInput.value = '';
            passwordInput.value = '';
            modal.classList.add('cw-visible');
            setMode('signin');
        }
        function closeModal() { modal.classList.remove('cw-visible'); }

        openBtn?.addEventListener('click', openModal);
        document.getElementById('auth-modal-close')?.addEventListener('click', closeModal);
        modal.addEventListener('click', (e) => { if (e.target === modal) closeModal(); });
        document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && modal.classList.contains('cw-visible')) closeModal(); });

        function showError(msg) { errorEl.innerText = msg; errorEl.classList.remove('hidden'); infoEl.classList.add('hidden'); }
        function showInfo(msg) { infoEl.innerText = msg; infoEl.classList.remove('hidden'); errorEl.classList.add('hidden'); }

        submitBtn?.addEventListener('click', async () => {
            if (!supabaseClient) { showError('Accounts are not set up yet on this deployment.'); return; }
            const email = emailInput.value.trim();
            const password = passwordInput.value;
            if (!email || !/^\S+@\S+\.\S+$/.test(email)) { showError('Enter a valid email address.'); return; }
            if (!password || password.length < 6) { showError('Password must be at least 6 characters.'); return; }

            submitBtn.disabled = true;
            const originalLabel = submitBtn.innerText;
            submitBtn.innerText = 'Please wait…';
            try {
                if (mode === 'signup') {
                    const { data, error } = await supabaseClient.auth.signUp({ email, password });
                    if (error) {
                        // Some Supabase configs throw this outright for a duplicate email.
                        if (/already registered|already exists|user already/i.test(error.message || '')) {
                            setMode('signin');
                            emailInput.value = email;
                            passwordInput.value = '';
                            showError('An account with this email already exists — sign in instead, or use "Forgot password?" below.');
                            passwordInput.focus();
                            return;
                        }
                        throw error;
                    }
                    // With email confirmations on, Supabase deliberately returns a *success*
                    // response (no error) for a duplicate email too, to avoid leaking which
                    // emails are registered. The tell is an empty `identities` array — a
                    // genuinely new signup always has one identity attached.
                    const alreadyRegistered = !!data?.user && Array.isArray(data.user.identities) && data.user.identities.length === 0;
                    if (alreadyRegistered) {
                        setMode('signin');
                        emailInput.value = email;
                        passwordInput.value = '';
                        showError('An account with this email already exists — sign in instead, or use "Forgot password?" below.');
                        passwordInput.focus();
                        return;
                    }
                    if (data.session) {
                        showInfo('Account created! You\'re signed in.');
                        setTimeout(closeModal, 900);
                    } else {
                        showInfo('Account created — check your email to confirm before signing in.');
                    }
                } else {
                    const { error } = await supabaseClient.auth.signInWithPassword({ email, password });
                    if (error) {
                        if (/invalid login credentials/i.test(error.message || '')) {
                            showError('Incorrect email or password. New here? Use the Sign Up tab instead.');
                            return;
                        }
                        throw error;
                    }
                    closeModal();
                }
            } catch (err) {
                showError(err.message || 'Something went wrong — try again.');
            } finally {
                submitBtn.disabled = false;
                submitBtn.innerText = originalLabel;
            }
        });

        forgotLink?.addEventListener('click', async (e) => {
            e.preventDefault();
            if (!supabaseClient) return;
            const email = emailInput.value.trim();
            if (!email || !/^\S+@\S+\.\S+$/.test(email)) { showError('Enter your email above first, then click "Forgot password?" again.'); return; }
            const originalLabel = forgotLink.innerText;
            forgotLink.innerText = 'Sending…';
            try {
                // redirectTo must land on a page that includes this same script, since the
                // reset link carries a #type=recovery token that this file listens for below
                // (see the PASSWORD_RECOVERY branch) in order to show the "set a new password"
                // form — without that listener, the link just silently signs the user in.
                const { error } = await supabaseClient.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/account.html` });
                if (error) throw error;
                showInfo('Password reset email sent — click the link in that email, then set your new password there.');
            } catch (err) {
                showError(err.message || 'Could not send reset email.');
            } finally {
                forgotLink.innerText = originalLabel;
            }
        });
    }

    // ---------- Continue with Google ----------
    // Present on the same modal markup on index.html and account.html. Google handles both
    // "sign up" and "sign in" as a single flow — Supabase creates the account on first use and
    // just signs the user in on every visit after, so this button works regardless of which
    // tab (Sign In / Sign Up) is active.
    const googleBtn = document.getElementById('auth-google-btn');
    googleBtn?.addEventListener('click', async () => {
        if (!supabaseClient) {
            document.getElementById('auth-config-warning')?.classList.remove('hidden');
            return;
        }
        googleBtn.disabled = true;
        const originalHtml = googleBtn.innerHTML;
        googleBtn.innerHTML = 'Redirecting…';
        try {
            const { error } = await supabaseClient.auth.signInWithOAuth({
                provider: 'google',
                options: { redirectTo: `${window.location.origin}${window.location.pathname}` },
            });
            if (error) throw error;
            // On success the browser is being navigated to Google right now — nothing else to do.
        } catch (err) {
            const errorEl = document.getElementById('auth-error');
            const infoEl = document.getElementById('auth-info');
            if (errorEl) {
                errorEl.innerText = err.message || 'Could not start Google sign-in. Make sure the Google provider is enabled in your Supabase project.';
                errorEl.classList.remove('hidden');
            }
            infoEl?.classList.add('hidden');
            googleBtn.disabled = false;
            googleBtn.innerHTML = originalHtml;
        }
    });

    // ---------- "Forgot password" reset flow ----------
    // Supabase's reset-password link signs the visitor in automatically (that's how it proves
    // they own the inbox) and fires a PASSWORD_RECOVERY auth event instead of the usual
    // SIGNED_IN — so the fix for "it redirects but doesn't reset" is to catch that event and
    // make the visitor actually choose a new password before treating them as a normal
    // logged-in user. This modal is injected on demand so it works on any page that loads this
    // script, without needing matching markup added to every HTML file.
    let recoveryModal = null;
    function ensureRecoveryModal() {
        if (recoveryModal) return recoveryModal;
        const wrap = document.createElement('div');
        wrap.id = 'recovery-modal';
        wrap.className = 'cw-modal-backdrop';
        wrap.innerHTML = `
            <div class="cw-modal-card" style="max-width:380px;" role="dialog" aria-modal="true" aria-label="Set a new password">
                <div class="flex items-center justify-between px-4 py-3 border-b border-gray-800 bg-[#1e222b]">
                    <span class="text-sm font-bold">Set a new password</span>
                    <button type="button" data-recovery-close aria-label="Close" class="text-gray-500 hover:text-white cursor-pointer text-lg leading-none">✕</button>
                </div>
                <div class="p-4 space-y-3">
                    <p class="text-[11px] text-gray-500 leading-relaxed">You followed a password reset link. Choose a new password below to finish resetting it.</p>
                    <div>
                        <label class="block text-[10px] font-bold uppercase tracking-wider text-gray-500 mb-1.5">New password</label>
                        <input type="password" data-recovery-password placeholder="At least 6 characters" autocomplete="new-password"
                            class="w-full bg-gray-900 border border-gray-800 rounded text-sm px-3 py-2 text-gray-200 placeholder-gray-500 focus:outline-none focus:border-[#14d38a]">
                    </div>
                    <div>
                        <label class="block text-[10px] font-bold uppercase tracking-wider text-gray-500 mb-1.5">Confirm new password</label>
                        <input type="password" data-recovery-password-confirm placeholder="Repeat password" autocomplete="new-password"
                            class="w-full bg-gray-900 border border-gray-800 rounded text-sm px-3 py-2 text-gray-200 placeholder-gray-500 focus:outline-none focus:border-[#14d38a]">
                    </div>
                    <div data-recovery-error class="hidden text-[11px] text-[#ff4d6a] bg-[#ff4d6a]/10 border border-[#ff4d6a]/20 rounded p-2"></div>
                    <div data-recovery-info class="hidden text-[11px] text-[#14d38a] bg-[#14d38a]/10 border border-[#14d38a]/20 rounded p-2"></div>
                    <button type="button" data-recovery-submit class="w-full text-sm font-bold uppercase py-2.5 rounded bg-[#14d38a] text-[#0b0e11] hover:opacity-90 transition-all cursor-pointer">Set new password</button>
                </div>
            </div>`;
        document.body.appendChild(wrap);

        const pwInput = wrap.querySelector('[data-recovery-password]');
        const pwConfirmInput = wrap.querySelector('[data-recovery-password-confirm]');
        const errEl = wrap.querySelector('[data-recovery-error]');
        const infEl = wrap.querySelector('[data-recovery-info]');
        const submit = wrap.querySelector('[data-recovery-submit]');

        function showErr(msg) { errEl.innerText = msg; errEl.classList.remove('hidden'); infEl.classList.add('hidden'); }
        function showInf(msg) { infEl.innerText = msg; infEl.classList.remove('hidden'); errEl.classList.add('hidden'); }
        function close() { wrap.classList.remove('cw-visible'); }

        wrap.querySelector('[data-recovery-close]').addEventListener('click', close);
        wrap.addEventListener('click', (e) => { if (e.target === wrap) close(); });

        submit.addEventListener('click', async () => {
            const pw = pwInput.value;
            const pw2 = pwConfirmInput.value;
            if (!pw || pw.length < 6) { showErr('Password must be at least 6 characters.'); return; }
            if (pw !== pw2) { showErr('Passwords do not match.'); return; }
            submit.disabled = true;
            const original = submit.innerText;
            submit.innerText = 'Please wait…';
            try {
                const { error } = await supabaseClient.auth.updateUser({ password: pw });
                if (error) throw error;
                showInf('Password updated — you\'re signed in with your new password.');
                pwInput.value = '';
                pwConfirmInput.value = '';
                // Strip the recovery token out of the URL so refreshing the page doesn't
                // re-open this modal.
                window.history.replaceState({}, document.title, window.location.pathname);
                setTimeout(close, 1400);
            } catch (err) {
                showErr(err.message || 'Could not update password — the reset link may have expired. Request a new one and try again.');
            } finally {
                submit.disabled = false;
                submit.innerText = original;
            }
        });

        recoveryModal = wrap;
        return wrap;
    }
    function openRecoveryModal() {
        modal?.classList.remove('cw-visible'); // don't show both modals stacked at once
        ensureRecoveryModal().classList.add('cw-visible');
    }

    // ---------- Boot: check existing session, then react to changes ----------
    if (supabaseClient) {
        supabaseClient.auth.getSession().then(({ data }) => {
            currentUser = data?.session?.user || null;
            renderHeader();
            broadcastAuth();
        });
        supabaseClient.auth.onAuthStateChange((event, session) => {
            currentUser = session?.user || null;
            renderHeader();
            broadcastAuth();
            if (event === 'PASSWORD_RECOVERY') {
                openRecoveryModal();
            }
        });
    } else {
        renderHeader();
        broadcastAuth();
    }
})();

// ==== 21-invest.js ====
// ---------- Real Trading (invest.html): a self-contained "buy/sell real crypto" page. ----------
// Runs on invest.html only. This page is the dedicated home for REAL, real-money trading
// (fiat in/out via AlchemyPay) — kept on its own URL and its own bundle, deliberately separate
// from trade.html (practice/paper trading with virtual funds) so the two are never confused.
//
// 14-alchemypay.js (loaded right after this file, in its own IIFE) reads several identifiers —
// POPULAR_COINS, holdings, futuresPositions, selectedAsset, showToast, escapeHtml — as bare/
// ambient names, resolved through the shared top-level scope of the bundle (exactly like
// 01-state.js does for bundle-home.js). So everything alchemypay.js needs is declared here at
// TOP LEVEL, not inside an IIFE — an easy mistake (an IIFE would hide them and break the modal).
// This page doesn't track a portfolio itself (that's trade.html / account.html), so holdings/
// futuresPositions stay empty arrays — AlchemyPay still works fine with an empty set.

const POPULAR_COINS = ['BTC', 'ETH', 'SOL', 'BNB', 'XRP', 'DOGE', 'ADA', 'AVAX', 'LINK', 'DOT', 'TRX', 'LTC', 'SHIB', 'SUI', 'PEPE'];
const holdings = [];
const futuresPositions = [];
let selectedAsset = { baseAsset: 'BTC' };

const ESCAPE_HTML_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
function escapeHtml(str) {
    if (str === null || str === undefined) return '';
    return String(str).replace(/[&<>"']/g, (ch) => ESCAPE_HTML_MAP[ch]);
}
function fmtUsd(n, opts) {
    if (n === null || n === undefined || isNaN(n)) return '--';
    return `$${n.toLocaleString(undefined, opts || { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}
function priceFmt(price) {
    return price < 1 ? { minimumFractionDigits: 4, maximumFractionDigits: 6 } : { minimumFractionDigits: 2, maximumFractionDigits: 2 };
}
function showToast(message, tone = 'info') {
    const toneMap = {
        success: { color: 'var(--cw-green)', icon: '✓' },
        error: { color: 'var(--cw-red)', icon: '✕' },
        info: { color: 'var(--cw-cyan)', icon: 'ℹ' },
    };
    const { color, icon } = toneMap[tone] || toneMap.info;
    const el = document.createElement('div');
    el.className = 'toast-enter cw-toast rounded-lg pr-4 py-2.5 text-xs shadow-2xl max-w-xs border border-gray-800';
    el.style.setProperty('--cw-tone', color);
    const iconEl = document.createElement('span');
    iconEl.className = 'cw-toast-icon text-[13px]';
    iconEl.innerText = icon;
    const msgEl = document.createElement('span');
    msgEl.className = 'font-mono leading-snug pt-px';
    msgEl.innerText = message;
    el.appendChild(iconEl);
    el.appendChild(msgEl);
    const container = document.getElementById('toast-container');
    if (!container) return;
    container.appendChild(el);
    setTimeout(() => { el.classList.add('toast-leave'); setTimeout(() => el.remove(), 300); }, 4000);
}

async function fetchWithTimeout(url, ms = 9000) {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), ms);
    try { return await fetch(url, { signal: ctrl.signal }); } finally { clearTimeout(t); }
}

function setFeedStatus(state, label) {
    const dot = document.getElementById('feed-dot');
    const text = document.getElementById('feed-status-text');
    if (dot) dot.className = `status-dot status-${state === 'live' ? 'live' : state === 'error' ? 'error' : 'connecting'}`;
    if (text) text.innerText = label;
}

// ---------- Page UI (this part is safely IIFE-scoped — nothing else needs these names) ----------
(function () {
    const symbolInput = document.getElementById('invest-symbol-input');
    const symbolList = document.getElementById('invest-symbol-list');
    const popularChips = document.getElementById('invest-popular-chips');
    const priceEl = document.getElementById('invest-live-price');
    const changeEl = document.getElementById('invest-live-change');
    const nameEl = document.getElementById('invest-asset-name');
    const buyBtn = document.getElementById('invest-buy-btn');
    const sellBtn = document.getElementById('invest-sell-btn');

    let validSymbols = new Set();

    async function bootstrapSymbols() {
        try {
            const res = await fetchWithTimeout('https://api.binance.com/api/v3/ticker/price');
            const arr = await res.json();
            if (Array.isArray(arr)) {
                arr.forEach(row => {
                    if (row.symbol && row.symbol.endsWith('USDT')) validSymbols.add(row.symbol.replace('USDT', ''));
                });
            }
            if (symbolList) {
                symbolList.innerHTML = Array.from(validSymbols).sort().map(s => `<option value="${s}">`).join('');
            }
            setFeedStatus('live', 'Live');
        } catch (err) {
            setFeedStatus('error', 'Unavailable');
        }
    }

    async function refreshSelectedPrice() {
        const symbol = (symbolInput?.value || 'BTC').toUpperCase().trim();
        if (!symbol) return;
        try {
            const res = await fetchWithTimeout(`https://api.binance.com/api/v3/ticker/24hr?symbol=${symbol}USDT`);
            if (!res.ok) throw new Error('not found');
            const row = await res.json();
            const price = parseFloat(row.lastPrice);
            const change = parseFloat(row.priceChangePercent);
            if (priceEl) priceEl.innerText = fmtUsd(price, priceFmt(price));
            if (changeEl) {
                changeEl.innerText = isNaN(change) ? '--' : `${change >= 0 ? '+' : ''}${change.toFixed(2)}%`;
                changeEl.className = `block text-[11px] font-mono font-bold ${change > 0 ? 'text-[#14d38a]' : change < 0 ? 'text-[#ff4d6a]' : 'text-gray-500'}`;
            }
            if (nameEl) nameEl.innerText = symbol;
            selectedAsset = { baseAsset: symbol };
            setFeedStatus('live', 'Live');
        } catch (err) {
            if (priceEl) priceEl.innerText = '--';
            if (changeEl) changeEl.innerText = 'not found';
            setFeedStatus('error', 'Retry pending…');
        }
    }

    function renderPopularChips() {
        if (!popularChips) return;
        popularChips.innerHTML = POPULAR_COINS.slice(0, 10).map(sym => `
            <button type="button" class="invest-chip-btn text-[10px] font-mono font-bold px-2.5 py-1 rounded-full bg-gray-900 border border-gray-800 text-gray-400 hover:text-[#14d38a] hover:border-[#14d38a]/40 transition-all cursor-pointer" data-symbol="${escapeHtml(sym)}">${escapeHtml(sym)}</button>
        `).join('');
        popularChips.querySelectorAll('.invest-chip-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                symbolInput.value = btn.dataset.symbol;
                refreshSelectedPrice();
            });
        });
    }

    symbolInput?.addEventListener('change', refreshSelectedPrice);
    symbolInput?.addEventListener('keydown', (e) => { if (e.key === 'Enter') refreshSelectedPrice(); });

    buyBtn?.addEventListener('click', () => {
        const symbol = (symbolInput?.value || 'BTC').toUpperCase().trim();
        window.openAlchemyPayWidget?.('BUY', symbol);
    });
    sellBtn?.addEventListener('click', () => {
        const symbol = (symbolInput?.value || 'BTC').toUpperCase().trim();
        window.openAlchemyPayWidget?.('SELL', symbol);
    });

    renderPopularChips();
    bootstrapSymbols();
    refreshSelectedPrice();
    setInterval(refreshSelectedPrice, 8000);

    // Footer year, shared tiny touch used across every page's footer.
    const yearEl = document.getElementById('footer-year');
    if (yearEl) yearEl.innerText = new Date().getFullYear();
})();


// ==== 14-alchemypay.js ====
// ---------- Buy/Sell Crypto via AlchemyPay (fiat on/off-ramp widget) ----------
// AlchemyPay lets a person buy real crypto with a card/bank transfer, or sell real crypto back
// to fiat. It is NOT an exchange and cannot open or close a leveraged futures position — there
// is no "buy BTC 10x long" button on AlchemyPay's side, only "buy/sell the actual coin." So the
// Futures Positions panel wires its Fund/Cash Out buttons to the exact same widget: it's the
// on/off-ramp a person would use to move fiat into or out of the wallet they then trade futures
// from on their exchange of choice, not a way to place a leveraged order itself. That distinction
// is called out in the modal copy so it's never presented as something it isn't.
//
// Widget URL: AlchemyPay's "Page Integration" widget takes a signed query string (appId, crypto,
// network, a merchant-generated order number, and an HMAC-SHA256 'sign') — see
// server/src/server.js POST /api/alchemypay-widget-url, where that URL is built and signed. The
// AlchemyPay appSecret lives there only, never in this file or js/00-config.js.
//
// Completed-order detection: unlike a postMessage-based widget, AlchemyPay finishes an order by
// navigating the iframe to our own redirectUrl (ramp-return.html, same origin as this site) once
// the flow ends. That page immediately posts a message to us; we then ask our OWN backend
// (GET /api/alchemypay-order-status) to confirm the order with AlchemyPay's Query Order API
// rather than trusting the redirect alone, and only then log it to the signed-in visitor's
// account history in Supabase.

(function setupAlchemyPayWidget() {
    function resolveApiUrl(path) {
        const base = (CW_CONFIG.apiBaseUrl || '').replace(/\/$/, '');
        return /^https?:\/\//i.test(path) ? path : `${base}${path}`;
    }

    async function fetchAlchemyPayWidgetUrl(mode, cryptoSymbol) {
        const body = { mode, symbol: cryptoSymbol };

        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 15000);
        try {
            const res = await fetch(resolveApiUrl('/api/alchemypay-widget-url'), {
                method: 'POST',
                headers: { 'content-type': 'application/json' },
                body: JSON.stringify(body),
                signal: controller.signal,
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.widgetUrl) {
                throw new Error(data?.error || `Widget session request failed (${res.status})`);
            }
            return data; // { widgetUrl, merchantOrderNo, side }
        } finally {
            clearTimeout(timer);
        }
    }

    async function fetchAlchemyPayOrderStatus(orderNo, side) {
        const url = resolveApiUrl(`/api/alchemypay-order-status?orderNo=${encodeURIComponent(orderNo)}&side=${side}`);
        const res = await fetch(url);
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data?.error || `Order status request failed (${res.status})`);
        return data;
    }

    // Assets offered in the "change asset" dropdown: curated popular list, plus whatever the
    // person already holds or has open futures positions in, plus whatever's on-screen right now.
    function availableAssetList() {
        const set = new Set(POPULAR_COINS);
        holdings.forEach(h => set.add(h.symbol));
        futuresPositions.forEach(p => set.add(p.symbol));
        if (selectedAsset && selectedAsset.baseAsset) set.add(selectedAsset.baseAsset);
        return Array.from(set);
    }

    // ---------- Modal DOM (built once, reused for every open) ----------
    const backdrop = document.createElement('div');
    backdrop.id = 'alchemypay-modal';
    backdrop.className = 'cw-modal-backdrop';
    backdrop.innerHTML = `
        <div class="cw-modal-card" style="max-width:480px; padding:0; overflow-x:hidden;" role="dialog" aria-modal="true" aria-label="Buy or sell crypto">
            <div class="flex items-center justify-between px-4 py-3 border-b border-gray-800 bg-[#1e222b]">
                <div class="flex items-center gap-2">
                    <h2 id="alchemypay-modal-title" class="text-sm font-bold text-white">Buy Crypto</h2>
                    <span class="text-[9px] font-bold uppercase px-1.5 py-0.5 rounded bg-gray-800 text-gray-400 border border-gray-700">via AlchemyPay</span>
                </div>
                <button id="alchemypay-close-btn" class="text-gray-500 hover:text-white cursor-pointer text-lg leading-none">✕</button>
            </div>
            <div id="alchemypay-futures-note" class="hidden px-4 py-2 text-[10.5px] leading-snug text-amber-300 bg-amber-500/10 border-b border-amber-500/20">
                This funds/cashes out real spot crypto with fiat — it does not open or close a leveraged futures position. Move the funds to your exchange's futures wallet afterward.
            </div>
            <div id="alchemypay-signin-note" class="hidden px-4 py-2 text-[10.5px] leading-snug text-gray-400 bg-gray-800/40 border-b border-gray-800">
                You're not signed in, so this purchase won't be saved to a My Account history. <button id="alchemypay-signin-cta" type="button" class="text-[#14d38a] font-bold hover:underline cursor-pointer">Sign in first →</button>
            </div>
            <div class="px-4 py-2.5 border-b border-gray-800 bg-[#14161c] flex items-center gap-2">
                <label for="alchemypay-asset-select" class="text-[10px] text-gray-500 uppercase font-bold shrink-0">Asset</label>
                <select id="alchemypay-asset-select" class="w-full bg-gray-900 border border-gray-800 rounded text-[11px] px-2 py-1.5 text-gray-200 focus:outline-none focus:border-[#14d38a]"></select>
            </div>
            <div id="alchemypay-modal-body" style="min-height:200px;"></div>
        </div>`;
    document.body.appendChild(backdrop);

    const titleEl = document.getElementById('alchemypay-modal-title');
    const futuresNoteEl = document.getElementById('alchemypay-futures-note');
    const signinNoteEl = document.getElementById('alchemypay-signin-note');
    const assetSelect = document.getElementById('alchemypay-asset-select');
    const bodyEl = document.getElementById('alchemypay-modal-body');

    document.getElementById('alchemypay-signin-cta')?.addEventListener('click', () => {
        toggleModal(false);
        document.getElementById('auth-open-btn')?.click();
    });

    let currentMode = 'BUY';
    let activeIframe = null;
    let currentOrderNo = null;
    let currentSide = 'buy';

    // Bumped on every renderBody() call so a slow/late-arriving fetch from a previous open (or a
    // rapid asset/mode switch) can never overwrite what's currently on screen.
    let renderToken = 0;

    async function renderBody() {
        const myToken = ++renderToken;
        bodyEl.innerHTML = `
            <div class="p-5 text-center text-gray-500 text-xs">
                Starting a secure session…
            </div>`;
        activeIframe = null;
        currentOrderNo = null;

        const symbol = assetSelect.value || 'BTC';
        try {
            const { widgetUrl, merchantOrderNo, side } = await fetchAlchemyPayWidgetUrl(currentMode, symbol);
            if (myToken !== renderToken) return; // superseded by a newer open/switch
            currentOrderNo = merchantOrderNo;
            currentSide = side || (currentMode === 'SELL' ? 'sell' : 'buy');
            // Fixed 640px was taller than most phone screens (with the header/notes bars above it
            // also eating vertical space), pushing AlchemyPay's own Buy/Sell button below the
            // fold with no way to reach it. min(640px, 75dvh) keeps the desktop size but shrinks
            // to fit short mobile viewports; the modal card itself also scrolls now as a fallback
            // (see .cw-modal-card in styles.css).
            bodyEl.innerHTML = `<iframe id="alchemypay-iframe" title="AlchemyPay On/Off Ramp Widget" src="${widgetUrl}" allow="camera;microphone;payment" allowtransparency="true" referrerpolicy="strict-origin-when-cross-origin" style="width:100%;height:min(640px, 75vh);height:min(640px, 75dvh);border:0;display:block;"></iframe>`;
            activeIframe = document.getElementById('alchemypay-iframe');
        } catch (err) {
            if (myToken !== renderToken) return;
            console.error('[CryptoBolt] Failed to start AlchemyPay widget session:', err?.message || err);
            bodyEl.innerHTML = `
                <div class="p-5 text-center">
                    <p class="text-xs text-gray-300 mb-2">Couldn't start the Buy/Sell session.</p>
                    <p class="text-[10.5px] text-gray-500 leading-relaxed mb-3">${escapeHtml(err?.message || 'Please try again in a moment.')}</p>
                    <button id="alchemypay-retry-btn" type="button" class="inline-block text-[11px] px-3 py-1.5 rounded bg-[#14d38a] text-[#0b0e11] font-bold hover:opacity-90 transition-all cursor-pointer">Retry</button>
                </div>`;
            document.getElementById('alchemypay-retry-btn')?.addEventListener('click', renderBody);
        }
    }

    function populateAssetSelect(preset) {
        const assets = availableAssetList();
        assetSelect.innerHTML = assets.map(sym => `<option value="${escapeHtml(sym)}">${escapeHtml(sym)}</option>`).join('');
        if (preset && assets.includes(preset)) assetSelect.value = preset;
    }

    function toggleModal(show) {
        backdrop.classList.toggle('cw-visible', show);
        if (!show) { bodyEl.innerHTML = ''; activeIframe = null; currentOrderNo = null; } // drop the iframe when closed so a paused KYC/payment session doesn't linger
    }

    function openAlchemyPayWidget(mode, presetSymbol, opts = {}) {
        currentMode = mode === 'SELL' ? 'SELL' : 'BUY';
        titleEl.innerText = currentMode === 'BUY' ? 'Buy Crypto' : 'Sell Crypto';
        futuresNoteEl.classList.toggle('hidden', !opts.isFutures);
        signinNoteEl.classList.toggle('hidden', !!window.cwAuth?.getUser?.() || !window.cwAuth?.isConfigured?.());
        populateAssetSelect((presetSymbol || 'BTC').toUpperCase());
        renderBody();
        toggleModal(true);
    }
    window.openAlchemyPayWidget = openAlchemyPayWidget; // exposed for reuse (e.g. from a future coin-row quick action)

    assetSelect.addEventListener('change', renderBody);
    document.getElementById('alchemypay-close-btn').addEventListener('click', () => toggleModal(false));
    backdrop.addEventListener('click', (e) => { if (e.target === backdrop) toggleModal(false); });
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && backdrop.classList.contains('cw-visible')) toggleModal(false);
    });

    // ---------- Capture completed real orders and save them to the signed-in account ----------
    // Recorded orders we've already saved this session, so a duplicate redirect/postMessage
    // never double-writes a purchase.
    const recordedOrderIds = new Set();

    // AlchemyPay's Query Order response shape (and even its status field) differs between onramp
    // (string statuses like "FINISHED") and offramp (numeric-string statuses like "4" for payment
    // success) — see https://alchemypay.readme.io/docs/query-order-2. Normalize both into one shape.
    function normalizeOrder(order, side) {
        if (!order) return null;
        if (side === 'sell') {
            const ok = order.status === '4' || order.status === 4;
            return {
                ok,
                cryptoAmount: Number(order.cryptoAmount ?? order.cryptoActualAmount),
                fiatAmount: Number(order.fiatAmount),
                symbol: String(order.crypto || '').toUpperCase(),
                fiatCurrency: String(order.fiat || 'USD').toUpperCase(),
                orderNo: order.orderNo || order.merchantOrderNo,
            };
        }
        const ok = order.status === 'FINISHED';
        return {
            ok,
            cryptoAmount: Number(order.cryptoQuantity),
            fiatAmount: Number(order.amount),
            symbol: String(order.crypto || '').toUpperCase(),
            fiatCurrency: String(order.fiat || 'USD').toUpperCase(),
            orderNo: order.orderNo || order.merchantOrderNo,
        };
    }

    async function recordCompletedOrder(merchantOrderNo, side) {
        if (!merchantOrderNo || recordedOrderIds.has(merchantOrderNo)) return;

        const client = window.cwAuth?.getClient?.();
        const user = window.cwAuth?.getUser?.();
        if (!client || !user) return; // guest checkout — nothing to attribute this to

        // The order can take a moment to settle on AlchemyPay's side right after the redirect
        // fires, so poll a few times before giving up rather than reporting failure prematurely.
        let normalized = null;
        for (let attempt = 0; attempt < 4; attempt++) {
            try {
                const raw = await fetchAlchemyPayOrderStatus(merchantOrderNo, side);
                normalized = normalizeOrder(raw, side);
                if (normalized?.ok) break;
            } catch (err) {
                console.warn('[CryptoBolt] AlchemyPay order status check failed:', err?.message || err);
            }
            if (attempt < 3) await new Promise(r => setTimeout(r, 4000));
        }

        if (!normalized?.ok) {
            console.warn('[CryptoBolt] AlchemyPay order not confirmed finished yet, skipping account save:', merchantOrderNo);
            return;
        }

        recordedOrderIds.add(merchantOrderNo);

        if (!normalized.symbol || !normalized.cryptoAmount || !normalized.fiatAmount) {
            console.warn('[CryptoBolt] AlchemyPay order payload missing expected fields, skipping save:', normalized);
            return;
        }

        const row = {
            user_id: user.id,
            side: side === 'sell' ? 'sell' : 'buy',
            symbol: normalized.symbol,
            crypto_amount: normalized.cryptoAmount,
            fiat_amount: normalized.fiatAmount,
            fiat_currency: normalized.fiatCurrency,
            price_usd: normalized.fiatAmount / normalized.cryptoAmount,
            provider: 'alchemypay',
            alchemypay_order_no: normalized.orderNo ? String(normalized.orderNo) : merchantOrderNo,
            status: 'completed',
        };

        try {
            const { error } = await client.from('purchases').insert(row);
            if (error) throw error;
            showToast(`Saved to your account: ${row.side === 'buy' ? 'bought' : 'sold'} ${normalized.cryptoAmount} ${normalized.symbol}.`, 'success');
        } catch (err) {
            console.error('[CryptoBolt] Failed to save purchase to Supabase:', err.message || err);
            showToast('Order completed, but saving it to your account failed — check My Account later.', 'error');
        }
    }

    // ramp-return.html (same origin, loaded inside the iframe once AlchemyPay's flow ends)
    // posts this message up to us so we know to go check the order's real status.
    window.addEventListener('message', (message) => {
        if (!activeIframe || message.source !== activeIframe.contentWindow) return;
        if (message?.data?.event_id === 'ALCHEMYPAY_ORDER_REDIRECT') {
            const orderNo = message.data.merchantOrderNo || currentOrderNo;
            const side = message.data.side || currentSide;
            if (orderNo) recordCompletedOrder(orderNo, side);
        }
    });

    // ---------- Button wiring ----------
    function currentChartSymbol() {
        return (selectedAsset && selectedAsset.baseAsset) || 'BTC';
    }
    function firstHoldingSymbol() {
        return (holdings[0] && holdings[0].symbol) || currentChartSymbol();
    }
    function firstFuturesSymbol() {
        return (futuresPositions[0] && futuresPositions[0].symbol) || currentChartSymbol();
    }

    document.getElementById('chart-buy-btn')?.addEventListener('click', () => openAlchemyPayWidget('BUY', currentChartSymbol()));
    document.getElementById('chart-sell-btn')?.addEventListener('click', () => openAlchemyPayWidget('SELL', currentChartSymbol()));

    document.getElementById('portfolio-buy-btn')?.addEventListener('click', () => openAlchemyPayWidget('BUY', firstHoldingSymbol()));
    document.getElementById('portfolio-sell-btn')?.addEventListener('click', () => openAlchemyPayWidget('SELL', firstHoldingSymbol()));

    document.getElementById('futures-buy-btn')?.addEventListener('click', () => openAlchemyPayWidget('BUY', firstFuturesSymbol(), { isFutures: true }));
    document.getElementById('futures-sell-btn')?.addEventListener('click', () => openAlchemyPayWidget('SELL', firstFuturesSymbol(), { isFutures: true }));
})();

// ==== 20-scroll-reveal.js ====
// ---------- Scroll-reveal for cards (shared across every bundle) ----------
// Cards marked `.cw-reveal` fade/slide into view the first time they cross into the viewport,
// then stay revealed (no re-hiding on scroll-out) — a common, tasteful modern-dashboard touch.
// This used to live inline in 12-events-init.js, which only ships in bundle-home.js — any page
// whose bundle didn't include that file (trade.html, account.html, ...) rendered every
// `.cw-reveal` card permanently stuck at opacity:0 (see css/styles.css), i.e. a blank page below
// the header. Pulled out into its own tiny module, included in every bundle, so that can't
// happen again regardless of which other modules a given page needs.
(function setupScrollReveal() {
    if (!('IntersectionObserver' in window)) {
        document.querySelectorAll('.cw-reveal').forEach(el => el.classList.add('cw-in-view'));
        return;
    }
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('cw-in-view');
                observer.unobserve(entry.target);
            }
        });
    }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });
    document.querySelectorAll('.cw-reveal').forEach((el, i) => {
        el.style.transitionDelay = `${Math.min(i * 40, 240)}ms`;
        observer.observe(el);
    });
})();